contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 depositAmount, uint256 otherAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= depositAmount);

        uint256 creditedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 creditedAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || creditedAfter == 0);
    }
}

