// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 depositAmount, uint256 otherAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint256 creditedBefore;
        try c.balances(address(this)) returns (uint256 __r) { creditedBefore = __r; } catch { return; }
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 creditedAfter;
        try c.balances(address(this)) returns (uint256 __r) { creditedAfter = __r; } catch { return; }
        assertTrue(reverted || creditedAfter == 0);
    }

    function testFuzz_run(uint256 depositAmount, uint256 otherAmount) public {
        _run(depositAmount, otherAmount);
    }

    receive() external payable {}
}
